{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE distribution_analytics AS WITH item_level AS ( SELECT a.order_name, a.saleorderitemcode, a.order_timestamp, a.order_type, a.manifested_timestamp, a.warehouse_name, a.last_updated, b.store FROM snitch_db.maplemonk.warehouse_sla_performance a LEFT JOIN warehouse_b2b_performance b ON a.order_name = b.order_name WHERE a.marketplace_mapped = \'STORE\' AND a.order_type <> \'NSO\' AND a.order_name NOT ILIKE \'QC%\' AND ( (a.warehouse_name IN (\'SAPL-WH1\', \'SAPL-WH2\')) OR (a.warehouse_name = \'SAPL-NORTH-TAURU\' AND a.order_timestamp >= \'2026-03-06\') ) AND a.sla_status not ilike \'%cancel%\' AND a.order_timestamp >= \'2026-02-15\' ), dedup AS ( SELECT * FROM item_level QUALIFY ROW_NUMBER() OVER ( PARTITION BY order_name, saleorderitemcode ORDER BY last_updated DESC NULLS LAST ) = 1 ), uc AS ( SELECT order_name, MAX(order_timestamp) AS order_timestamp, MAX(order_type) AS order_type, MAX(manifested_timestamp) AS manifested_timestamp, MAX(warehouse_name) AS warehouse_name, COUNT(DISTINCT saleorderitemcode) AS distinct_itemcodes, COUNT(*) AS quantity, MAX(last_updated) AS last_updated, store FROM dedup GROUP BY order_name, store ), sto_data AS ( SELECT order_no, new_bill_no FROM snitch_db.maplemonk.logic_final_sto WHERE ORIGIN IN (\'WH-STORE\', \'WH-VIRTUAL\') QUALIFY ROW_NUMBER() OVER (PARTITION BY new_bill_no ORDER BY new_bill_no) = 1 ), rulebook AS ( SELECT store_name, upload_date, wh, best_tat, lane_classification, fresh_order_cutoff, rpl_order_cutoff, fresh_handover_day, rpl_handover_day, fresh_tat, rpl_tat FROM distribution_rule_book ), rulebook_matched AS ( SELECT u.order_name, rb.best_tat, rb.lane_classification, rb.fresh_order_cutoff, rb.rpl_order_cutoff, rb.fresh_handover_day, rb.rpl_handover_day, rb.fresh_tat, rb.rpl_tat FROM uc u LEFT JOIN rulebook rb ON UPPER(u.store) = UPPER(rb.store_name) AND ( (u.warehouse_name IN (\'SAPL-WH2\', \'SAPL-WH1\') AND rb.wh = \'South WH\') OR (u.warehouse_name IN (\'SAPL-NORTH-TAURU\') AND rb.wh = \'North WH\') ) AND rb.upload_date <= DATE_TRUNC(\'day\', u.order_timestamp) QUALIFY ROW_NUMBER() OVER ( PARTITION BY u.order_name ORDER BY rb.upload_date DESC NULLS LAST ) = 1 ), eshipz AS ( SELECT UPPER(t.value:invoice_number::STRING) AS unique_order_id, e.awb AS tracking_number, e.order_status AS eship_status, UPPER(e.details:tag::STRING) AS status, UPPER(e.slug) AS courier_partner, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP_NTZ(SUBSTRING(e.date::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\') ) AS logistics_created_timestamp, TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) AS logistics_delivery_timestamp, (TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:expected_delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) - INTERVAL \'11 hours\') AS logistics_expected_delivery_date, CASE WHEN LOWER(e.slug) LIKE \'%gati%\' THEN TRY_TO_TIMESTAMP_NTZ(SUBSTRING( e.details:checkpoints[array_size(e.details:checkpoints)-1]:date::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\') WHEN TRY_TO_TIMESTAMP_NTZ(e.tracking_pick_date, \'YYYY-MM-DD\"T\"HH24:MI:SS\') IS NOT NULL THEN TRY_TO_TIMESTAMP_NTZ(e.tracking_pick_date, \'YYYY-MM-DD\"T\"HH24:MI:SS\') WHEN NULLIF(e.tracking_pick_date, \'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ(TO_TIMESTAMP_TZ(e.tracking_pick_date, \'DY, DD MON YYYY HH24:MI:SS TZD\')) WHEN TRY_TO_TIMESTAMP_NTZ(REGEXP_REPLACE(e.tracking_pick_date, \'^.*, \', \'\'), \'DD MON YYYY HH24:MI:SS\') IS NOT NULL THEN TRY_TO_TIMESTAMP_NTZ(REGEXP_REPLACE(e.tracking_pick_date, \'^.*, \', \'\'), \'DD MON YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP_NTZ(NULLIF(e.tracking_pick_date, \'\')) END AS tracking_pick_date, CASE WHEN NULLIF(e.first_ofd_date, \'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ(TO_TIMESTAMP_TZ(e.first_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\')) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.first_ofd_date, \'\')) END AS first_ofd_date, CASE WHEN NULLIF(e.latest_ofd_date, \'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ(TO_TIMESTAMP_TZ(e.latest_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\')) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.latest_ofd_date, \'\')) END AS latest_ofd_date, e.delivery_attempts::NUMBER AS delivery_attempts, e.pickup_attempts::NUMBER AS pickup_attempts, e.tracking_link::STRING AS tracking_link, e.tracking_status::STRING AS tracking_status, e.tracking_sub_status::STRING AS tracking_sub_status, e.tracking_latest_location, e.tracking_latest_message, e.details:checkpoints[0]:\"city\"::STRING AS last_checkpoint_city, e.details:checkpoints[0]:\"state\"::STRING AS last_checkpoint_state, e.details:checkpoints[0]:\"remark\"::STRING AS last_checkpoint_remark, e.details:checkpoints[0]:\"subtag\"::STRING AS last_checkpoint_subtag, e.details:checkpoints[0]:\"tag\"::STRING AS last_checkpoint_tag, UPPER(e.order_details:receiver_address:city::STRING) AS receiver_city, UPPER(e.order_details:receiver_address:state::STRING) AS receiver_state, e.order_details:receiver_address:postal_code::STRING AS receiver_postal_code, CASE WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'DADRA AND NAGAR HAVELI\',\'GUJARAT\',\'MADHYA PRADESH\',\'CHHATISGARH\',\'GOA\',\'MAHARASHTRA\') THEN \'WEST\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'ANDHRA PRADESH\',\'KARNATAKA\',\'PONDICHERRY\',\'TAMIL NADU\',\'TELANGANA\',\'KERALA\') THEN \'SOUTH\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'CHANDIGARH\',\'DELHI\',\'HARYANA\',\'HIMACHAL PRADESH\',\'JAMMU AND KASHMIR\', \'PUNJAB\',\'RAJASTHAN\',\'UTTAR PRADESH\',\'UTTARAKHAND\') THEN \'NORTH\' WHEN UPPER(e.order_details:receiver_address:state::STRING) IN (\'ARUNACHAL PRADESH\',\'ASSAM\',\'BIHAR\',\'JHARKHAND\',\'MEGHALAYA\',\'MIZORAM\', \'NAGALAND\',\'ODISHA\',\'SIKKIM\',\'TRIPURA\',\'WEST BENGAL\') THEN \'EAST\' ELSE \'UNMAPPED\' END AS zone, e.details:pod_link::STRING AS pod_link, e.is_reverse::BOOLEAN AS is_reverse, package_count FROM snitch_db.maplemonk.eshipz_final_get_tracking e, LATERAL FLATTEN(input => e.gst_invoices) t ), joined AS ( SELECT u.order_name, u.order_timestamp, u.order_type, u.manifested_timestamp, u.warehouse_name, u.quantity, u.store, sd.new_bill_no AS invoice_number, rb.best_tat, rb.lane_classification, CASE WHEN u.order_type = \'FRESH\' THEN LEFT(rb.fresh_order_cutoff, 3) WHEN u.order_type = \'RPL\' THEN LEFT(rb.rpl_order_cutoff, 3) END AS target_order_day, CASE WHEN u.order_type = \'FRESH\' THEN RIGHT(rb.fresh_order_cutoff, 4) WHEN u.order_type = \'RPL\' THEN RIGHT(rb.rpl_order_cutoff, 4) END AS target_order_cutoff, CASE WHEN u.order_type = \'FRESH\' THEN LEFT(rb.fresh_handover_day, 3) WHEN u.order_type = \'RPL\' THEN LEFT(rb.rpl_handover_day, 3) END AS target_handover_day, CASE WHEN u.order_type = \'FRESH\' THEN RIGHT(rb.fresh_tat, 4) WHEN u.order_type = \'RPL\' THEN RIGHT(rb.rpl_tat, 4) END AS target_handover_cutoff, e.tracking_number, e.eship_status, e.status, e.courier_partner, e.logistics_created_timestamp, e.logistics_delivery_timestamp, e.logistics_expected_delivery_date, e.tracking_pick_date, e.first_ofd_date, e.latest_ofd_date, e.delivery_attempts, e.pickup_attempts, e.tracking_link, e.tracking_status, e.tracking_sub_status, e.tracking_latest_location, e.tracking_latest_message, e.last_checkpoint_city, e.last_checkpoint_state, e.last_checkpoint_remark, e.last_checkpoint_subtag, e.last_checkpoint_tag, e.receiver_city, e.receiver_state, e.receiver_postal_code, e.zone, e.pod_link, e.package_count FROM uc u LEFT JOIN sto_data sd ON UPPER(u.order_name) = UPPER(sd.order_no) LEFT JOIN rulebook_matched rb ON u.order_name = rb.order_name LEFT JOIN eshipz e ON UPPER(sd.new_bill_no) = UPPER(e.unique_order_id) AND e.is_reverse = FALSE ), placement_sla AS ( SELECT j.*, DATEADD(hour, CASE WHEN j.target_order_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) END WHEN j.target_order_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(j.target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(j.order_timestamp) + 7, 7), DATE_TRUNC(\'day\', j.order_timestamp)) ) AS order_cutoff_ts, CASE WHEN j.order_timestamp IS NULL OR j.target_order_day IS NULL OR j.target_order_cutoff IS NULL THEN NULL WHEN j.target_order_day = \'Mon\' THEN CASE WHEN DAYOFWEEKISO(j.order_timestamp) NOT IN (5, 6, 7, 1) THEN \'BREACHED\' WHEN j.order_timestamp > DATEADD(hour, CASE WHEN j.target_order_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) END WHEN j.target_order_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(1 - DAYOFWEEKISO(j.order_timestamp) + 7, 7), DATE_TRUNC(\'day\', j.order_timestamp))) THEN \'BREACHED\' WHEN DAYOFWEEKISO(j.order_timestamp) = 1 THEN \'WITHIN_SLA\' ELSE \'EARLY_CREATION\' END WHEN MOD( DECODE(j.target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(j.order_timestamp) + 7, 7 ) NOT IN (0, 1, 2) THEN \'BREACHED\' WHEN j.order_timestamp > DATEADD(hour, CASE WHEN j.target_order_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'AM\',\'\'))) END WHEN j.target_order_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(j.target_order_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(j.target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(j.order_timestamp) + 7, 7), DATE_TRUNC(\'day\', j.order_timestamp))) THEN \'BREACHED\' WHEN MOD( DECODE(j.target_order_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(j.order_timestamp) + 7, 7 ) = 0 THEN \'WITHIN_SLA\' ELSE \'EARLY_CREATION\' END AS order_placement_sla FROM joined j ), sla_calc AS ( SELECT p.*, CASE WHEN p.order_timestamp IS NULL THEN NULL WHEN p.order_placement_sla IN (\'WITHIN_SLA\', \'EARLY_CREATION\') AND p.target_handover_day IS NOT NULL AND p.target_handover_cutoff IS NOT NULL THEN DATEADD(hour, CASE WHEN p.target_handover_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) END WHEN p.target_handover_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(p.target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(p.order_timestamp) + 7, 7), DATE_TRUNC(\'day\', p.order_timestamp))) WHEN p.order_placement_sla = \'BREACHED\' THEN CASE WHEN EXTRACT(HOUR FROM p.order_timestamp) < 9 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'18 hour\' WHEN EXTRACT(HOUR FROM p.order_timestamp) < 16 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'5 hour\' ELSE DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'18 hour\' END ELSE NULL END AS handover_deadline_ts, CASE WHEN p.manifested_timestamp IS NULL AND CASE WHEN p.order_timestamp IS NULL THEN NULL WHEN p.order_placement_sla IN (\'WITHIN_SLA\', \'EARLY_CREATION\') AND p.target_handover_day IS NOT NULL AND p.target_handover_cutoff IS NOT NULL THEN DATEADD(hour, CASE WHEN p.target_handover_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) END WHEN p.target_handover_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(p.target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(p.order_timestamp) + 7,7), DATE_TRUNC(\'day\', p.order_timestamp))) WHEN p.order_placement_sla = \'BREACHED\' THEN CASE WHEN EXTRACT(HOUR FROM p.order_timestamp) < 9 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'18 hour\' WHEN EXTRACT(HOUR FROM p.order_timestamp) < 16 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'5 hour\' ELSE DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'18 hour\' END ELSE NULL END IS NULL THEN \'FUTURE SLA\' WHEN p.manifested_timestamp IS NULL AND CASE WHEN p.order_timestamp IS NULL THEN NULL WHEN p.order_placement_sla IN (\'WITHIN_SLA\', \'EARLY_CREATION\') AND p.target_handover_day IS NOT NULL AND p.target_handover_cutoff IS NOT NULL THEN DATEADD(hour, CASE WHEN p.target_handover_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) END WHEN p.target_handover_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(p.target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(p.order_timestamp) + 7,7), DATE_TRUNC(\'day\', p.order_timestamp))) WHEN p.order_placement_sla = \'BREACHED\' THEN CASE WHEN EXTRACT(HOUR FROM p.order_timestamp) < 9 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'18 hour\' WHEN EXTRACT(HOUR FROM p.order_timestamp) < 16 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'5 hour\' ELSE DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'18 hour\' END ELSE NULL END < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN p.manifested_timestamp IS NULL THEN \'FUTURE SLA\' WHEN p.manifested_timestamp > CASE WHEN p.order_timestamp IS NULL THEN NULL WHEN p.order_placement_sla IN (\'WITHIN_SLA\', \'EARLY_CREATION\') AND p.target_handover_day IS NOT NULL AND p.target_handover_cutoff IS NOT NULL THEN DATEADD(hour, CASE WHEN p.target_handover_cutoff ILIKE \'%AM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) = 12 THEN 0 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'AM\',\'\'))) END WHEN p.target_handover_cutoff ILIKE \'%PM%\' THEN CASE WHEN TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) = 12 THEN 12 ELSE TRY_TO_NUMBER(TRIM(REPLACE(UPPER(p.target_handover_cutoff),\'PM\',\'\'))) + 12 END END, DATEADD(day, MOD(DECODE(p.target_handover_day,\'Mon\',1,\'Tue\',2,\'Wed\',3,\'Thu\',4,\'Fri\',5,\'Sat\',6,\'Sun\',7) - DAYOFWEEKISO(p.order_timestamp) + 7,7), DATE_TRUNC(\'day\', p.order_timestamp))) WHEN p.order_placement_sla = \'BREACHED\' THEN CASE WHEN EXTRACT(HOUR FROM p.order_timestamp) < 9 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'18 hour\' WHEN EXTRACT(HOUR FROM p.order_timestamp) < 16 THEN DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'5 hour\' ELSE DATE_TRUNC(\'day\', p.order_timestamp) + INTERVAL \'1 day\' + INTERVAL \'18 hour\' END ELSE NULL END THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS handover_sla, CASE WHEN handover_deadline_ts IS NULL THEN NULL ELSE DATE_TRUNC(\'day\', handover_deadline_ts) + INTERVAL \'22 hour\' END AS pickup_tat, CASE WHEN p.tracking_pick_date IS NULL THEN NULL WHEN LOWER(p.courier_partner) LIKE \'%porter%\' OR LOWER(p.courier_partner) LIKE \'%self%\' THEN CASE WHEN p.receiver_city IN (\'BANGALORE\',\'BENGALURU\') THEN DATE_TRUNC(\'day\', p.tracking_pick_date) + INTERVAL \'23 hour\' ELSE NULL END WHEN LOWER(p.courier_partner) LIKE \'%movemate%\' OR LOWER(p.courier_partner) LIKE \'%mmn%\' THEN CASE WHEN p.receiver_state = \'KARNATAKA\' THEN DATE_TRUNC(\'day\', p.tracking_pick_date + INTERVAL \'1 day\') + INTERVAL \'23 hour\' ELSE NULL END ELSE DATEADD(\'day\', p.best_tat, p.tracking_pick_date) END AS delivery_tat, CASE WHEN p.tracking_pick_date IS NULL AND CASE WHEN handover_deadline_ts IS NULL OR p.logistics_created_timestamp IS NULL THEN NULL WHEN p.logistics_created_timestamp > handover_deadline_ts THEN CASE WHEN EXTRACT(HOUR FROM p.logistics_created_timestamp) < 18 THEN DATE_TRUNC(\'day\', p.logistics_created_timestamp) + INTERVAL \'22 hour\' ELSE DATE_TRUNC(\'day\', p.logistics_created_timestamp + INTERVAL \'1 day\') + INTERVAL \'22 hour\' END ELSE CASE WHEN EXTRACT(HOUR FROM handover_deadline_ts) < 18 THEN DATE_TRUNC(\'day\', handover_deadline_ts) + INTERVAL \'22 hour\' ELSE DATE_TRUNC(\'day\', handover_deadline_ts + INTERVAL \'1 day\') + INTERVAL \'22 hour\' END END < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN p.tracking_pick_date IS NULL THEN \'FUTURE SLA\' WHEN p.tracking_pick_date > CASE WHEN handover_deadline_ts IS NULL OR p.logistics_created_timestamp IS NULL THEN NULL WHEN p.logistics_created_timestamp > handover_deadline_ts THEN CASE WHEN EXTRACT(HOUR FROM p.logistics_created_timestamp) < 18 THEN DATE_TRUNC(\'day\', p.logistics_created_timestamp) + INTERVAL \'22 hour\' ELSE DATE_TRUNC(\'day\', p.logistics_created_timestamp + INTERVAL \'1 day\') + INTERVAL \'22 hour\' END ELSE CASE WHEN EXTRACT(HOUR FROM handover_deadline_ts) < 18 THEN DATE_TRUNC(\'day\', handover_deadline_ts) + INTERVAL \'22 hour\' ELSE DATE_TRUNC(\'day\', handover_deadline_ts + INTERVAL \'1 day\') + INTERVAL \'22 hour\' END END THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS pickup_sla, CASE WHEN p.logistics_delivery_timestamp IS NULL AND DATEADD(\'day\', p.best_tat, p.tracking_pick_date) IS NULL THEN \'FUTURE SLA\' WHEN p.logistics_delivery_timestamp IS NULL AND DATEADD(\'day\', p.best_tat, p.tracking_pick_date) < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN p.logistics_delivery_timestamp IS NULL AND DATEADD(\'day\', p.best_tat, p.tracking_pick_date) >= CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN p.logistics_delivery_timestamp > DATEADD(\'day\', p.best_tat, p.tracking_pick_date) THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS delivery_sla, CASE WHEN p.logistics_delivery_timestamp IS NOT NULL AND p.logistics_expected_delivery_date IS NOT NULL AND p.logistics_delivery_timestamp <= p.logistics_expected_delivery_date THEN \'WITHIN_SLA\' WHEN p.logistics_delivery_timestamp IS NOT NULL AND p.logistics_expected_delivery_date IS NOT NULL AND p.logistics_delivery_timestamp > p.logistics_expected_delivery_date THEN \'BREACHED\' WHEN p.logistics_delivery_timestamp IS NULL AND p.logistics_expected_delivery_date IS NOT NULL AND p.logistics_expected_delivery_date > CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN p.logistics_delivery_timestamp IS NULL AND p.logistics_expected_delivery_date IS NOT NULL AND p.logistics_expected_delivery_date <= CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' ELSE NULL END AS logistics_delivery_sla, CASE WHEN p.tracking_number IN ( \'53540504592\',\'53540504802\',\'53540504706\',\'53540503542\',\'53540504522\', \'53540505745\',\'53540503903\',\'53540505023\',\'53540505174\',\'53540503726\', \'53540505233\',\'53540506003\',\'53540504640\',\'53540505200\',\'53540503855\', \'53540506692\',\'53540503612\',\'53540505911\',\'53540503940\',\'53